import java.util.Scanner;

public class Main {
    private static final long M = 1000000007L;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        scanner.close();

        long result = (power(27, n) - power(7, n)) % M;
        result = (result + M) % M;
        System.out.println(result);
    }

    private static long power(long n, long k) {
        long result = 1;

        if (k > 0) {
            result *= power(n, k / 2);
            result %= M;

            result *= result;
            result %= M;

            if (k % 2 == 1) {
                result *= n;
                result %= M;
            }
        }

        return result;
    }
}

